begin("phone-numbers")
fixed("The legacy extension field is ext. followed by exactly four ASCII digits with no space. Leading zeros are allowed.","ext.","0123456789",4)
fixed("A local dial token starts # and has exactly seven ASCII digits after it. No other punctuation or spaces.","#","0123456789",7)
fixed("The radio handset code is R followed by exactly six ASCII digits and suffix /voice.","R","0123456789",6,"/voice")
fixed("A test phone is the literal +999 followed immediately by exactly eight ASCII digits. Format only; do not validate real country allocation.","+999","0123456789",8)
fixed("A PBX route is sip: followed by exactly five ASCII digits and literal @pbx.test. No real SIP parsing beyond this format.","sip:","0123456789",5,"@pbx.test")
